from django.db import migrations, models


def carry_over_sequences(apps, schema_editor):
    """把「比赛代码-FY」的流水进度搬到「cid<比赛ID>-FY」，避免改编号规则后重号。"""
    import re

    Contract = apps.get_model('contracts', 'Contract')
    NumberSequence = apps.get_model('contracts', 'NumberSequence')
    db = schema_editor.connection.alias

    name = str(schema_editor.connection.settings_dict.get('NAME') or '')
    found = re.search(r'comp_(\d+)', name)
    competition_id = int(found.group(1)) if found else None
    if competition_id is None:
        # 测试库/非常规库名：没有可搬迁的历史流水，直接跳过
        return

    max_by_fy = {}
    for number in Contract.objects.using(db).exclude(unified_number='').values_list(
            'unified_number', flat=True):
        parts = str(number).rsplit('-', 2)
        if len(parts) != 3:
            continue
        try:
            seq = int(parts[2])
        except (TypeError, ValueError):
            continue
        fy_part = parts[1]
        max_by_fy[fy_part] = max(max_by_fy.get(fy_part, 0), seq)

    for fy_part, last in max_by_fy.items():
        key = f'cid{competition_id}-{fy_part}'
        row, _created = NumberSequence.objects.using(db).get_or_create(
            key=key, defaults={'last_value': last})
        if not _created and row.last_value < last:
            row.last_value = last
            row.save(update_fields=['last_value'])


